import math

def prime_fib(n):
    def is_prime(p):
        if p < 2: return False
        for k in range(2, int(math.sqrt(p)) + 1):
            if p % k == 0: return False
        return True

    fibs = [0, 1]
    count = 0
    while True:
        next_fib = fibs[-1] + fibs[-2]
        fibs.append(next_fib)
        if is_prime(next_fib):
            count += 1
        if count == n:
            return next_fib
